#include <bits/stdc++.h>
using namespace std;using U=uint32_t;using L=uint64_t;
void need(bool ok,string m){if(!ok)throw runtime_error(m);}
vector<U> graph(int u){int m=32-__builtin_clz(u-1),n=m+2;vector<U>a(n);a[0]=2;for(int j=0;j<m;j++){int v=j+2;a[v]|=1;if((u-1)>>(m-1-j)&1)a[1]|=1u<<v;else a[v]|=2;for(int k=j+1;k<m;k++)a[v]|=1u<<(k+2);}return a;}
L path_count(vector<U> const&a){int n=a.size(),N=1<<n;vector<L>d(n*N);for(int v=0;v<n;v++)d[(1<<v)*n+v]=1;for(int mask=1;mask<N;mask++)for(int v=0;v<n;v++)if(d[mask*n+v])for(U x=a[v]&~mask;x;x&=x-1){int w=__builtin_ctz(x);d[(mask|(1<<w))*n+w]+=d[mask*n+v];}L ans=0;for(int v=0;v<n;v++)ans+=d[(N-1)*n+v];return ans;}
bool strong(vector<U>const&a){int n=a.size();for(int v=0;v<n;v++){U seen=1u<<v,prev=0;while(prev!=seen){prev=seen;for(int j=0;j<n;j++)if(seen>>j&1)seen|=a[j];}if(seen!=(1u<<n)-1)return false;}return true;}
vector<U> ext(vector<U>a,U b){int n=a.size();a.push_back(b);for(int j=0;j<n;j++)if(!(b>>j&1))a[j]|=1u<<n;return a;}
struct Profile{int n,N;L H;vector<L>s,e,Q;Profile(vector<U>a){n=a.size();N=1<<n;vector<L>d(n*N),f(n*N);for(int v=0;v<n;v++)d[(1<<v)*n+v]=f[(1<<v)*n+v]=1;for(int mask=1;mask<N;mask++)for(int v=0;v<n;v++)if(mask>>v&1){int z=mask^(1<<v);for(int w=0;w<n;w++)if(z>>w&1){if(a[w]>>v&1)d[mask*n+v]+=d[z*n+w];else f[mask*n+v]+=f[z*n+w];}}H=0;s.resize(n);e.resize(n);for(int v=0;v<n;v++){e[v]=d[(N-1)*n+v];s[v]=f[(N-1)*n+v];H+=e[v];}Q.resize(n*n);for(int S=1;S<N-1;S++)for(int i=0;i<n;i++)if(S>>i&1)for(int j=0;j<n;j++)if(!(S>>j&1))Q[i*n+j]+=d[S*n+i]*f[((N-1)^S)*n+j];}
L val(U b){L h=0;for(int i=0;i<n;i++){if(b>>i&1)h+=s[i];else {h+=e[i];for(int j=0;j<n;j++)if(b>>j&1)h+=Q[i*n+j];}}return h;}};
// Independent path-word enumeration, simultaneously distributed to all new-edge orientations.
vector<L> completions(vector<U>const&a){int n=a.size(),N=n+2,B=2*n+1;U full=(1u<<B)-1;vector<L>count(1u<<B);vector<int>p(N);iota(p.begin(),p.end(),0);uint64_t words=0,valid=0;do{words++;U ones=0,zeros=0;bool ok=true;for(int k=0;k<N-1;k++){int v=p[k],w=p[k+1];if(v<n&&w<n){if(!(a[v]>>w&1)){ok=false;break;}}else{int fresh=max(v,w),old=min(v,w),bit=(fresh==n?old:n+old);if(v==fresh)ones|=1u<<bit;else zeros|=1u<<bit;}}if(!ok)continue;need(!(ones&zeros),"inconsistent permutation");valid++;U free=full^(ones|zeros);for(U sub=free;;sub=(sub-1)&free){count[ones|sub]++;if(!sub)break;}}while(next_permutation(p.begin(),p.end()));cerr<<"literal_permutations="<<words<<" consistent_words="<<valid<<"\n";return count;}
int main(){for(int u:{9,17,19,35}){auto a=graph(u);int n=a.size();need(strong(a),"base strong");L H=path_count(a);auto independent=completions(a);map<L,int>hist;vector<int>samples;for(U b=0;b<(1u<<n);b++){auto first=ext(a,b);Profile prof(first);need(prof.H==path_count(first),"first direct DP");for(U c=0;c<(1u<<(n+1));c++){U code=b|(c<<n);L value=prof.val(c);need(value==independent[code],"full independent comparison");hist[value]++;if(code%997==0)need(value==path_count(ext(first,c)),"sample full DP");}}cout<<"u="<<u<<" n="<<n<<" H="<<H<<" rows=";for(auto x:a)cout<<x<<",";cout<<" total_extensions="<<independent.size()<<" distinct_values="<<hist.size()<<" minimum="<<hist.begin()->first<<" maximum="<<hist.rbegin()->first<<"\n";for(int sign:{-1,1}){int target=6*u+sign;if(hist.count(target))continue;uint64_t pow5=1;for(int j=0;j<n+2;j++)pow5*=5;uint64_t cub=uint64_t(target)*target*target;bool div=true;for(int d=H;d<target;d++)if(target%d==0)div=false;if(pow5>cub&&div){cout<<"OBSTRUCTION u="<<u<<" target="<<target<<" strong_cutoff="<<n+2<<" pow5="<<pow5<<" target_cube="<<cub<<" extension_multiplicity=0\n";}}ofstream f("hist_u"+to_string(u)+".tsv");f<<"H\tmultiplicity\n";for(auto kv:hist)f<<kv.first<<"\t"<<kv.second<<"\n";}cout<<"PASS: all extension counts agree entrywise between independent literal-word and subset-DP cover algorithms.\n";}
